class Solution {
  public int maximumWidth(int[] planks) {
    java.util.TreeMap<Integer, Integer> cnt = new java.util.TreeMap<>();
    for (int p : planks) cnt.merge(p, 1, Integer::sum);
    int[] vals = new int[cnt.size()], counts = new int[cnt.size()];
    int idx = 0;
    for (java.util.Map.Entry<Integer, Integer> e : cnt.entrySet()) {
      vals[idx] = e.getKey();
      counts[idx++] = e.getValue();
    }
    java.util.HashMap<Long, Long> pairs = new java.util.HashMap<>();
    for (int a = 0; a < vals.length; a++) {
      for (int b = a; b < vals.length; b++) {
        long add = a == b ? counts[a] / 2 : Math.min(counts[a], counts[b]);
        if (add > 0) pairs.merge((long) vals[a] + vals[b], add, Long::sum);
      }
    }
    long best = 1;
    for (java.util.Map.Entry<Long, Long> e : pairs.entrySet()) {
      long h = e.getKey();
      long total = e.getValue() + (h <= Integer.MAX_VALUE ? cnt.getOrDefault((int) h, 0) : 0);
      best = Math.max(best, total);
    }
    for (int c : counts) best = Math.max(best, c);
    return (int) best;
  }
}
